def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    change_ratio = change / v1
    percent_increase = change_ratio * 100

    return {
        "value": percent_increase,
        "trace": {
            "initial_value": v1,
            "final_value": v2,
            "change": change,
            "change_ratio": change_ratio,
